// Build here, run only on a fabric node with the hsaco generated by mori.jit:
// test_fabric_batch_copy --hsaco <path> [--devices 0,1] [--quick]
#include <hip/hip_runtime_api.h>

#include <algorithm>
#include <exception>
#include <iostream>
#include <memory>
#include <random>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

#include "mori/io/engine.hpp"
#include "src/io/fabric/backend_impl.hpp"
#include "src/io/fabric/copy_test_hooks.hpp"

using namespace mori::io;
namespace {
void Require(bool ok, const std::string& message) {
  if (!ok) throw std::runtime_error(message);
}
void Hip(hipError_t err) { Require(err == hipSuccess, hipGetErrorString(err)); }
unsigned char Pattern(uint64_t seed, uint64_t byte) {
  uint64_t x = (seed + 1) * 0x9e3779b97f4a7c15ull + byte;
  x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ull;
  return static_cast<unsigned char>((x ^ (x >> 27)) >> 19);
}
constexpr unsigned char kSentinel = 0xa5;
struct Pair {
  int local, remote;
  IOEngine a{"fabric_batch_local", {"127.0.0.1", 0}};
  IOEngine b{"fabric_batch_remote", {"127.0.0.1", 0}};
  Pair(int l, int r) : local(l), remote(r) {
    FabricBackendConfig cfg;
    cfg.numStreams = 8;
    cfg.numEvents = 4096;
    a.CreateBackend(BackendType::FABRIC, cfg);
    b.CreateBackend(BackendType::FABRIC, cfg);
    a.RegisterRemoteEngine(b.GetEngineDesc());
    b.RegisterRemoteEngine(a.GetEngineDesc());
  }
};
struct Buffers {
  Pair& pair;
  void* local{nullptr};
  void* remote{nullptr};
  MemoryDesc ld{}, rd{};
  Buffers(Pair& p, size_t bytes) : pair(p) {
    local = FabricMalloc(bytes, p.local);
    remote = FabricMalloc(bytes, p.remote);
    Require(local && remote, "FabricMalloc failed");
    ld = p.a.RegisterMemory(local, bytes, p.local, MemoryLocationType::GPU);
    rd = p.b.RegisterMemory(remote, bytes, p.remote, MemoryLocationType::GPU);
  }
  ~Buffers() {
    pair.a.DeregisterMemory(ld);
    pair.b.DeregisterMemory(rd);
    (void)hipSetDevice(pair.local);
    FabricFree(local);
    (void)hipSetDevice(pair.remote);
    FabricFree(remote);
  }
  IOEngineSession Session() {
    auto s = pair.a.CreateSession(ld, rd);
    Require(s.has_value(), "could not create Fabric session");
    return *s;
  }
  void Upload(const std::vector<unsigned char>& source, bool read) {
    std::vector<unsigned char> sentinel(source.size(), kSentinel);
    Hip(hipSetDevice(read ? pair.remote : pair.local));
    Hip(hipMemcpy(read ? remote : local, source.data(), source.size(), hipMemcpyHostToDevice));
    Hip(hipSetDevice(read ? pair.local : pair.remote));
    Hip(hipMemcpy(read ? local : remote, sentinel.data(), sentinel.size(), hipMemcpyHostToDevice));
  }
  std::vector<unsigned char> Download(size_t bytes, bool read) {
    std::vector<unsigned char> result(bytes);
    Hip(hipSetDevice(read ? pair.local : pair.remote));
    Hip(hipMemcpy(result.data(), read ? local : remote, bytes, hipMemcpyDeviceToHost));
    return result;
  }
};
void Submit(IOEngineSession& s, bool read, const SizeVec& local, const SizeVec& remote,
            const SizeVec& sizes, TransferStatus* status) {
  auto id = s.AllocateTransferUniqueId();
  if (read)
    s.BatchRead(local, remote, sizes, status, id);
  else
    s.BatchWrite(local, remote, sizes, status, id);
}
void Success(TransferStatus& status) {
  status.Wait();
  Require(status.Succeeded(), "transfer failed: " + status.Message());
}

// Whole-allocation comparison includes every padding byte, not just segment payloads.
void Case(Pair& p, const SizeVec& sizes, int alignment, bool read, uint64_t seed) {
  SizeVec lo, ro;
  size_t lc = alignment == 0 ? 16 : 17;
  size_t rc = alignment == 0 ? 16 : (alignment == 1 ? 17 : 19);
  for (size_t size : sizes) {
    lo.push_back(lc);
    ro.push_back(rc);
    lc += ((size + 15) / 16) * 16 + 32;
    rc += ((size + 15) / 16) * 16 + 48;
  }
  size_t bytes = std::max(lc, rc) + 32;
  Buffers mem(p, bytes);
  std::vector<unsigned char> source(bytes, 0x31), expected(bytes, kSentinel);
  for (size_t i = 0; i < sizes.size(); ++i) {
    for (size_t j = 0; j < sizes[i]; ++j) {
      auto value = Pattern(seed + i, j);
      source[(read ? ro : lo)[i] + j] = value;
      expected[(read ? lo : ro)[i] + j] = value;
    }
  }
  mem.Upload(source, read);
  auto s = mem.Session();
  TransferStatus status;
  if (sizes.size() == 1) {
    auto id = s.AllocateTransferUniqueId();
    if (read)
      s.Read(lo[0], ro[0], sizes[0], &status, id);
    else
      s.Write(lo[0], ro[0], sizes[0], &status, id);
  } else {
    // Exercise remote sorting as well as non-contiguous addressing.
    auto l = lo, r = ro, z = sizes;
    std::reverse(l.begin(), l.end());
    std::reverse(r.begin(), r.end());
    std::reverse(z.begin(), z.end());
    Submit(s, read, l, r, z, &status);
  }
  Success(status);
  Require(mem.Download(bytes, read) == expected, "payload or sentinel mismatch");
}

void Fallback(Pair& p) {
  // Both engines still have no module. Small copies succeed in both directions.
  Case(p, {4095, 656, 1}, 0, false, 1);
  Case(p, {4095, 656, 1}, 0, true, 2);
  constexpr size_t mib = 1024 * 1024;
  Buffers mem(p, 8 * mib);
  std::vector<unsigned char> source(8 * mib, 0x39);
  mem.Upload(source, false);
  auto s = mem.Session();
  TransferStatus status;
  fabric::CopyTestHooks hooks;
  fabric::SetCopyTestHooks(&hooks);
  // A small segment sorts first; two later 3 MiB segments merge to 6 MiB.
  Submit(s, false, {0, mib, 4 * mib}, {0, mib, 4 * mib}, {16, 3 * mib, 3 * mib}, &status);
  fabric::SetCopyTestHooks(nullptr);
  status.Wait();
  Require(status.Failed() && status.Message().find("kernel not loaded") != std::string::npos &&
              status.Message().find(">= 4 MiB") != std::string::npos &&
              status.Message().find("livelock") != std::string::npos,
          "fallback rejection must report its cause");
  Require(hooks.successfulLaunches == 0 && hooks.drainCalls == 0,
          "fallback rejection submitted work");
  Require(
      mem.Download(source.size(), false) == std::vector<unsigned char>(source.size(), kSentinel),
      "rejected batch changed destination");
}

void Failure(Pair& p, bool eventFailure, bool drainFailure, bool read) {
  constexpr size_t count = 1025, stride = 8192, payload = 4096;
  Buffers mem(p, count * stride);
  std::vector<unsigned char> source(count * stride, 0x31), expected(count * stride, kSentinel);
  SizeVec offsets, sizes(count, payload);
  for (size_t i = 0; i < count; ++i) {
    offsets.push_back(i * stride);
    for (size_t j = 0; j < payload; ++j) {
      source[i * stride + j] = Pattern(i, j);
      if (eventFailure || i < 512) expected[i * stride + j] = source[i * stride + j];
    }
  }
  mem.Upload(source, read);
  auto s = mem.Session();
  TransferStatus status;
  fabric::CopyTestHooks hooks;
  hooks.failLaunch = eventFailure ? 0 : 2;
  hooks.failEventRecord = eventFailure;
  hooks.drainError = drainFailure ? hipErrorUnknown : hipSuccess;
  bool before = false, after = false;
  hooks.onDrain = [&](bool done, hipStream_t stream) {
    Require(!status.Failed() && !status.Succeeded(), "terminal status published before drain");
    if (done) {
      after = true;
      Hip(hipStreamQuery(stream));
      Require(mem.Download(source.size(), read) == expected, "drain returned before copy finished");
      Hip(hipSetDevice(p.local));
    } else
      before = true;
  };
  fabric::SetCopyTestHooks(&hooks);
  try {
    Submit(s, read, offsets, offsets, sizes, &status);
  } catch (...) {
    fabric::SetCopyTestHooks(nullptr);
    throw;
  }
  fabric::SetCopyTestHooks(nullptr);
  status.Wait();
  std::string original =
      std::string(eventFailure ? "hipEventRecord" : "copy launch") +
      " failed: " + hipGetErrorString(eventFailure ? hooks.eventError : hooks.launchError);
  Require(status.Code() == StatusCode::ERR_GPU_OP &&
              status.Message().find(original) != std::string::npos,
          "lost original error: " + status.Message());
  Require(before && after && hooks.drainCalls == 1 &&
              hooks.successfulLaunches == (eventFailure ? 3u : 1u),
          "incorrect drain/launch count");
  Require((status.Message().find("drain failed") != std::string::npos) == drainFailure,
          "drain error not appended correctly");
  if (drainFailure)
    Require(status.Message().find(hipGetErrorString(hipErrorUnknown)) != std::string::npos,
            "lost drain error");
  Require(mem.Download(source.size(), read) == expected,
          "destination changed after terminal status");
}

void Concurrent(Pair& p, bool read, bool quick) {
  constexpr size_t threads = 4, segments = 17, stride = 64, payload = 32;
  size_t batches = quick ? 16 : 256;  // full run: 1024 batches, 8 pooled streams
  size_t region = segments * stride;
  size_t bytes = threads * batches * region;
  Buffers mem(p, bytes);
  std::vector<unsigned char> source(bytes, 0x31), expected(bytes, kSentinel);
  for (size_t b = 0; b < threads * batches; ++b)
    for (size_t i = 0; i < segments; ++i)
      for (size_t j = 0; j < payload; ++j)
        expected[b * region + i * stride + j] = source[b * region + i * stride + j] =
            Pattern(b * segments + i, j);
  mem.Upload(source, read);
  // Create sessions before workers; workers only submit to existing cached sessions.
  std::vector<IOEngineSession> sessions;
  for (size_t t = 0; t < threads; ++t) sessions.push_back(mem.Session());
  std::vector<std::unique_ptr<TransferStatus>> statuses;
  for (size_t b = 0; b < threads * batches; ++b) statuses.emplace_back(new TransferStatus);
  std::vector<std::thread> workers;
  std::vector<std::exception_ptr> errors(threads);
  for (size_t t = 0; t < threads; ++t)
    workers.emplace_back([&, t]() {
      try {
        for (size_t b = t * batches; b < (t + 1) * batches; ++b) {
          SizeVec offsets, sizes(segments, payload);
          for (size_t i = 0; i < segments; ++i) offsets.push_back(b * region + i * stride);
          Submit(sessions[t], read, offsets, offsets, sizes, statuses[b].get());
          // Planner and kernarg host storage have been destroyed before the next submission.
        }
      } catch (...) {
        errors[t] = std::current_exception();
      }
    });
  for (auto& worker : workers) worker.join();
  // All batches are submitted before any wait. Even on error, drain all issued statuses.
  for (auto& status : statuses)
    if (!status->Init()) status->Wait();
  for (const auto& error : errors)
    if (error) std::rethrow_exception(error);
  for (auto& status : statuses) Success(*status);
  Require(mem.Download(bytes, read) == expected, "concurrent kernarg/payload mismatch");
}

void Large(Pair& p, bool read, int alignment) {
  // Stream host initialization/verification in 16 MiB windows, keeping host RAM bounded.
  constexpr size_t bytes = (size_t{1} << 32) + 4097;
  constexpr size_t allocationBytes = bytes + 64;
  constexpr size_t window = 16 * 1024 * 1024;
  const size_t localOffset = alignment == 0 ? 16 : 17;
  const size_t remoteOffset = alignment == 0 ? 16 : (alignment == 1 ? 17 : 19);
  const size_t srcOffset = read ? remoteOffset : localOffset;
  const size_t dstOffset = read ? localOffset : remoteOffset;
  Buffers mem(p, allocationBytes);
  std::vector<unsigned char> source(window), sentinel(window, kSentinel), result(window);
  for (size_t off = 0; off < allocationBytes; off += window) {
    size_t n = std::min(window, allocationBytes - off);
    for (size_t j = 0; j < n; ++j) source[j] = Pattern(78, off + j);
    Hip(hipSetDevice(read ? p.remote : p.local));
    Hip(hipMemcpy(static_cast<char*>(read ? mem.remote : mem.local) + off, source.data(), n,
                  hipMemcpyHostToDevice));
    Hip(hipSetDevice(read ? p.local : p.remote));
    Hip(hipMemcpy(static_cast<char*>(read ? mem.local : mem.remote) + off, sentinel.data(), n,
                  hipMemcpyHostToDevice));
  }
  auto s = mem.Session();
  TransferStatus status;
  if (read)
    s.Read(localOffset, remoteOffset, bytes, &status, s.AllocateTransferUniqueId());
  else
    s.Write(localOffset, remoteOffset, bytes, &status, s.AllocateTransferUniqueId());
  Success(status);
  Hip(hipSetDevice(read ? p.local : p.remote));
  for (size_t off = 0; off < allocationBytes; off += window) {
    size_t n = std::min(window, allocationBytes - off);
    Hip(hipMemcpy(result.data(), static_cast<char*>(read ? mem.local : mem.remote) + off, n,
                  hipMemcpyDeviceToHost));
    for (size_t j = 0; j < n; ++j) {
      auto want = off + j >= dstOffset && off + j < bytes + dstOffset
                      ? Pattern(78, off + j - dstOffset + srcOffset)
                      : kSentinel;
      if (result[j] != want)
        throw std::runtime_error(">4 GiB copy mismatch at " + std::to_string(off + j));
    }
  }
}
}  // namespace

int main(int argc, char** argv) {
  try {
    std::string hsaco;
    int first = -1, second = -1;
    bool quick = false;
    for (int i = 1; i < argc; ++i) {
      std::string arg = argv[i];
      if (arg == "--hsaco" && i + 1 < argc)
        hsaco = argv[++i];
      else if (arg == "--quick")
        quick = true;
      else if (arg == "--devices" && i + 1 < argc) {
        std::string devices = argv[++i];
        auto comma = devices.find(',');
        Require(comma != std::string::npos, "--devices requires two device indices");
        first = std::stoi(devices.substr(0, comma));
        second = std::stoi(devices.substr(comma + 1));
      } else
        throw std::runtime_error(
            "usage: test_fabric_batch_copy --hsaco <path> [--devices 0,1] [--quick]");
    }
    int count = 0;
    std::vector<int> capable;
    if (hipGetDeviceCount(&count) == hipSuccess)
      for (int i = 0; i < count; ++i)
        if (fabric::DeviceSupportsFabric(i)) capable.push_back(i);
    if (capable.size() < 2) {
      std::cout << "SKIP: requires at least two fabric-capable GPUs\n";
      return 0;
    }
    if (first < 0) {
      first = capable[0];
      second = capable[1];
    }
    Require(first != second && std::find(capable.begin(), capable.end(), first) != capable.end() &&
                std::find(capable.begin(), capable.end(), second) != capable.end(),
            "invalid fabric devices");
    Require(!hsaco.empty(), "--hsaco must point to the JIT-produced fabric_copy hsaco");
    Require(fabric::VpodKeySame(fabric::ReadVpodKey(first), fabric::ReadVpodKey(second)),
            "devices are not in the same ready fabric vPOD");
    Pair p(first, second);
    Fallback(p);
    p.a.LoadFabricCopyModule(hsaco);
    p.b.LoadFabricCopyModule(hsaco);
    std::mt19937 rng(17);
    for (bool read : {false, true}) {
      for (size_t n : {1, 2, 7, 16, 17, 512, 513, 1000, 5000}) {
        for (int alignment : {0, 1, 2}) {
          SizeVec sizes;
          const size_t choices[] = {1, 15, 16, 656, 4095, 4096, 4097};
          for (size_t i = 0; i < n; ++i) sizes.push_back(choices[rng() % 7]);
          Case(p, sizes, alignment, read, n * 3 + alignment);
        }
      }
      for (size_t size : {1, 15, 16, 656, 4095, 4096, 4097, 1048576, 33554432})
        for (int alignment : {0, 1, 2}) {
          Case(p, {size}, alignment, read, size);
          if (!quick || size <= 1048576) Case(p, SizeVec(7, size), alignment, read, size + 3);
        }
      Case(p, {0, 0, 0}, 0, read, 1);
      Case(p, {0, 4097, 0, 656}, 1, read, 2);
      Case(p, {}, 0, read, 3);
      Failure(p, false, false, read);
      Failure(p, true, false, read);
      Failure(p, true, true, read);
      Concurrent(p, read, quick);
      if (!quick)
        for (int alignment : {0, 1, 2}) Large(p, read, alignment);
    }
    std::cout << "PASS: Fabric batch copy"
              << (quick ? " (quick; >4 GiB and full stress omitted)" : "") << '\n';
    return 0;
  } catch (const std::exception& e) {
    fabric::SetCopyTestHooks(nullptr);
    std::cerr << "FAIL: " << e.what() << '\n';
    return 1;
  }
}
